1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible animated circle with hover effects">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      --bg: #fff;
19	      --fg: #2563eb;
20	      --shadow: rgba(0, 0, 0, 0.1);
21	    }
22	    @media (prefers-color-scheme: dark) {
23	      :root {
24	        --bg: #111;
25	        --fg: #60a5fa;
26	        --shadow: rgba(0, 0, 0, 0.6);
27	      }
28	    }
29	    body {
30	      min-height: 100dvh;
31	      display: grid;
32	      place-items: center;
33	      padding: 1rem;
34	      background: var(--bg);
35	      color: var(--fg);
36	      font-family: system-ui, -apple-system, sans-serif;
37	    }
38	    main {
39	      width: 100%;
40	      display: flex;
41	      justify-content: center;
42	    }
43	    svg {
44	      display: block;
45	      width: min(400px, 100%);
46	      height: auto;
47	      overflow: visible;
48	      filter: drop-shadow(0 8px 16px var(--shadow));
49	    }
50	    circle {
51	      transition: opacity 0.3s ease;
52	      transform-box: fill-box;
53	      transform-origin: center;
54	      opacity: 0.9;
55	    }
56	    svg:focus {
57	      outline: none;
58	    }
59	    svg:focus-visible {
60	      outline: 3px solid var(--fg);
61	      outline-offset: 8px;
62	      border-radius: 50%;
63	    }
64	    @media (hover: hover) {
65	      circle:hover {
66	        opacity: 1;
67	      }
68	    }
69	    circle:active,
70	    svg:focus-visible circle {
71	      opacity: 1;
72	    }
73	    @media (prefers-reduced-motion: no-preference) {
74	      circle {
75	        transition:
76	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
77	          opacity 0.3s ease;
78	      }
79	      circle:active,
80	      svg:focus-visible circle {
81	        transform: scale(1.05);
82	      }
83	    }
84	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
85	      circle:hover {
86	        transform: scale(1.05);
87	      }
88	    }
89	  </style>
90	</head>
91	<body>
92	  <main>
93	    <svg viewBox="0 0 400 400" role="img" aria-labelledby="circle-title" tabindex="0" xmlns="http://www.w3.org/2000/svg">
94	      <title id="circle-title">Blue circle that grows slightly on hover or focus</title>
95	      <circle cx="200" cy="200" r="180" fill="currentColor"/>
96	    </svg>
97	  </main>
98	</body>
99	</html>
